export const sourceDocuments: SourceDocument[] = [
  // ==================== INTELLIGENCIA ARTIFICIAL Y MACHINE LEARNING ====================
  { id: 'aiml-001', title: 'Artificial Intelligence: A Modern Approach', author: 'Stuart Russell, Peter Norvig', year: 2021, content: 'Artificial intelligence is the field of computer science dedicated to creating systems capable of performing tasks that typically require human intelligence. These tasks include learning, reasoning, problem-solving, perception, and language understanding. Modern AI systems leverage machine learning techniques, particularly deep neural networks, to learn hierarchical representations from data.', url: 'https://aima.cs.berkeley.edu/', doi: '10.1145/3454347', language: 'en', type: 'book' },
  { id: 'aiml-002', title: 'Deep Learning', author: 'Ian Goodfellow, Yoshua Bengio, Aaron Courville', year: 2016, content: 'Deep learning is a subset of machine learning that uses artificial neural networks with multiple layers to progressively extract higher-level features from raw input. For image processing, lower layers may identify edges, while higher layers identify concepts relevant to human interpretation such as digits, letters, or faces. The backpropagation algorithm computes gradients efficiently.', url: 'https://www.deeplearningbook.org/', doi: '10.1038/nature14539', language: 'en', type: 'book' },
  { id: 'aiml-003', title: 'Pattern Recognition and Machine Learning', author: 'Christopher Bishop', year: 2006, content: 'Machine learning is a scientific discipline that explores the construction and study of algorithms that can learn from data. Such algorithms operate by building a model from example inputs in order to make data-driven predictions or decisions. Pattern recognition focuses on the automatic discovery of patterns in data through statistical analysis.', url: 'https://www.microsoft.com/en-us/research/people/cmbishop/', doi: '10.1007/978-0-387-45528-0', language: 'en', type: 'book' },
  { id: 'aiml-004', title: 'Attention Is All You Need', author: 'Ashish Vaswani, Noam Shazeer, Niki Parmar', year: 2017, content: 'We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely. Self-attention allows the model to weigh the importance of different words in a sequence when making predictions. Multi-head attention enables the model to jointly attend to information from different positions.', url: 'https://arxiv.org/abs/1706.03762', doi: '10.48550/arXiv.1706.03762', language: 'en', type: 'academic' },
  { id: 'aiml-005', title: 'ImageNet Classification with Deep Convolutional Neural Networks', author: 'Alex Krizhevsky, Ilya Sutskever, Geoffrey Hinton', year: 2012, content: 'We trained a large, deep convolutional neural network to classify the 1.2 million high-resolution images in the ImageNet LSVRC-2010 contest into 1000 different classes. The neural network has 60 million parameters and 650,000 neurons. Dropout regularization prevented overfitting. ReLU activation functions accelerated training compared to sigmoid units.', url: 'https://papers.nips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html', doi: '10.1145/3065386', language: 'en', type: 'academic' },
  { id: 'aiml-006', title: 'Generative Adversarial Networks', author: 'Ian Goodfellow, Jean Pouget-Abadie, Mehdi Mirza', year: 2014, content: 'We propose a new framework for estimating generative models via an adversarial process, in which we simultaneously train two models: a generative model G that captures the data distribution, and a discriminative model D. The training procedure for G is to maximize the probability of D making a mistake.', url: 'https://arxiv.org/abs/1406.2661', doi: '10.48550/arXiv.1406.2661', language: 'en', type: 'academic' },
  { id: 'aiml-007', title: 'BERT: Pre-training of Deep Bidirectional Transformers', author: 'Jacob Devlin, Ming-Wei Chang, Kenton Lee', year: 2019, content: 'We introduce BERT, which stands for Bidirectional Encoder Representations from Transformers. BERT is designed to pre-train deep bidirectional representations from unlabeled text by jointly conditioning on both left and right context. The masked language model randomly masks tokens and predicts them.', url: 'https://arxiv.org/abs/1810.04805', doi: '10.18653/v1/N19-1423', language: 'en', type: 'academic' },
  { id: 'aiml-008', title: 'Playing Atari with Deep Reinforcement Learning', author: 'Volodymyr Mnih, Koray Kavukcuoglu, David Silver', year: 2013, content: 'We present the first deep learning model to successfully learn control policies directly from high-dimensional sensory input using reinforcement learning. The model is a convolutional neural network trained with a variant of Q-learning. Experience replay memory and separate target network stabilized training.', url: 'https://arxiv.org/abs/1312.5602', doi: '10.48550/arXiv.1312.5602', language: 'en', type: 'academic' },
  { id: 'aiml-009', title: 'Deep Residual Learning for Image Recognition', author: 'Kaiming He, Xiangyu Zhang, Shaoqing Ren, Jian Sun', year: 2016, content: 'Deeper neural networks are more difficult to train. We present a residual learning framework to ease the training of networks that are substantially deeper. We explicitly reformulate the layers as learning residual functions with reference to the layer inputs. Skip connections enable gradient flow through very deep networks.', url: 'https://arxiv.org/abs/1512.03385', doi: '10.1109/CVPR.2016.90', language: 'en', type: 'academic' },
  { id: 'aiml-010', title: 'Adam: A Method for Stochastic Optimization', author: 'Diederik Kingma, Jimmy Ba', year: 2015, content: 'We introduce Adam, an algorithm for first-order gradient-based optimization of stochastic objective functions, based on adaptive estimates of lower-order moments. The method is straightforward to implement, computationally efficient, and has little memory requirements. Adam combines the advantages of AdaGrad and RMSProp.', url: 'https://arxiv.org/abs/1412.6980', doi: '10.48550/arXiv.1412.6980', language: 'en', type: 'academic' },
  { id: 'aiml-011', title: 'Dropout: A Simple Way to Prevent Neural Networks from Overfitting', author: 'Nitish Srivastava, Geoffrey Hinton, Alex Krizhevsky', year: 2014, content: 'Deep neural nets with a large number of parameters are very powerful machine learning systems. However, overfitting is a serious problem. We propose dropout, where we drop units randomly during training. This prevents co-adaptation of feature detectors and significantly improves performance on supervised learning tasks.', url: 'https://jmlr.org/papers/v15/srivastava14a.html', doi: '10.5555/2627435.2670313', language: 'en', type: 'academic' },
  { id: 'aiml-012', title: 'Batch Normalization: Accelerating Deep Network Training', author: 'Sergey Ioffe, Christian Szegedy', year: 2015, content: 'Training deep neural networks is complicated by the internal covariate shift, where the distribution of each layer inputs changes during training. Batch normalization addresses this by normalizing layer inputs to have zero mean and unit variance for each mini-batch. This allows higher learning rates and acts as a regularizer.', url: 'https://arxiv.org/abs/1502.03167', doi: '10.48550/arXiv.1502.03167', language: 'en', type: 'academic' },
  { id: 'aiml-013', title: 'Layer Normalization', author: 'Jimmy Lei Ba, Jamie Ryan Kiros, Geoffrey Hinton', year: 2016, content: 'Layer normalization is a normalization technique designed for feed-forward neural networks and recurrent neural networks. Unlike batch normalization, layer normalization normalizes across features for each training case independently. This makes it effective for small batch sizes and sequence models.', url: 'https://arxiv.org/abs/1607.06450', doi: '10.48550/arXiv.1607.06450', language: 'en', type: 'academic' },
  { id: 'aiml-014', title: 'U-Net: Convolutional Networks for Biomedical Image Segmentation', author: 'Olaf Ronneberger, Philipp Fischer, Thomas Brox', year: 2015, content: 'We present a network and training strategy that relies on the strong use of data augmentation to use the available annotated samples more efficiently. The architecture consists of a contracting path to capture context and a symmetric expanding path that enables precise localization. Skip connections combine features from different resolution levels.', url: 'https://arxiv.org/abs/1505.04597', doi: '10.1007/978-3-319-24574-4_28', language: 'en', type: 'academic' },
  { id: 'aiml-015', title: 'XGBoost: A Scalable Tree Boosting System', author: 'Tianqi Chen, Carlos Guestrin', year: 2016, content: 'XGBoost is a scalable machine learning system for tree boosting. It is widely used in data science competitions and industry applications. The system handles sparse data efficiently and includes novel techniques for approximate tree learning. Cache-aware access patterns improve performance on modern hardware.', url: 'https://arxiv.org/abs/1603.02754', doi: '10.1145/2939672.2939785', language: 'en', type: 'academic' },
  { id: 'aiml-016', title: 'Random Forests', author: 'Leo Breiman', year: 2001, content: 'Random forests are a combination of tree predictors such that each tree depends on the values of a random vector sampled independently and with the same distribution for all trees in the forest. The generalization error for forests converges to a limit as the number of trees grows. Random forests are robust to overfitting.', url: 'https://link.springer.com/article/10.1023/A:1010933404324', doi: '10.1023/A:1010933404324', language: 'en', type: 'academic' },
  { id: 'aiml-017', title: 'Support Vector Machines', author: 'Corinna Cortes, Vladimir Vapnik', year: 1995, content: 'The support vector machine constructs a hyperplane that separates the training data with maximal margin. The margin is defined as the minimal distance from the hyperplane to the closest training point. Using the kernel trick, SVMs can efficiently perform non-linear classification by mapping inputs into high-dimensional feature spaces.', url: 'https://link.springer.com/article/10.1007/BF00994018', doi: '10.1007/BF00994018', language: 'en', type: 'academic' },
  { id: 'aiml-018', title: 'Long Short-Term Memory', author: 'Sepp Hochreiter, Jurgen Schmidhuber', year: 1997, content: 'Learning to store information over extended time intervals in recurrent neural networks is difficult. We introduce long short-term memory, a recurrent network architecture containing special units called memory cells. These cells have input, output, and forget gates that control information flow, enabling learning of long-term dependencies.', url: 'https://www.bioinf.jku.at/publications/older/2604.pdf', doi: '10.1162/neco.1997.9.8.1735', language: 'en', type: 'academic' },
  { id: 'aiml-019', title: 'K-Means Clustering', author: 'Stuart Lloyd', year: 1982, content: 'Least squares quantization in PCM is an algorithm for placing quantization levels in order to minimize mean squared error. The algorithm iteratively assigns points to the nearest cluster center and recomputes centers as the mean of assigned points. This procedure converges to a local minimum of the distortion criterion.', url: 'https://ieeexplore.ieee.org/document/1056489', doi: '10.1109/TIT.1982.1056489', language: 'en', type: 'academic' },
  { id: 'aiml-020', title: 'Principal Component Analysis', author: 'Svante Wold, Kim Esbensen, Paul Geladi', year: 1987, content: 'Principal component analysis is a mathematical procedure that transforms a number of possibly correlated variables into a smaller number of uncorrelated variables called principal components. The first principal component accounts for as much of the variability in the data as possible, and each succeeding component accounts for the remaining variance.', url: 'https://www.sciencedirect.com/science/article/abs/pii/0169743987800849', doi: '10.1016/0169-7439(87)80084-9', language: 'en', type: 'academic' },

  // ==================== PROGRAMACION Y DESARROLLO ====================
  { id: 'prog-001', title: 'The C Programming Language', author: 'Brian Kernighan, Dennis Ritchie', year: 1988, content: 'C is a general-purpose programming language which features economy of expression, modern control flow and data structures, and a rich set of operators. C is not a very high level language, but its absence of restrictions make it convenient for many tasks. Pointers provide direct access to memory, enabling efficient system programming.', url: 'https://www.bell-labs.com/usr/dmr/www/cbook.html', doi: '10.5555/109517', language: 'en', type: 'book' },
  { id: 'prog-002', title: 'Structure and Interpretation of Computer Programs', author: 'Harold Abelson, Gerald Jay Sussman', year: 1996, content: 'A computer language is not just a way of getting a computer to perform operations but is a novel formal medium for expressing ideas about methodology. Programs must be written for people to read, and only incidentally for machines to execute. Abstraction and modularity manage complexity in large systems.', url: 'https://mitpress.mit.edu/sites/default/files/sicp/index.html', doi: '10.5555/291481', language: 'en', type: 'book' },
  { id: 'prog-003', title: 'The Pragmatic Programmer', author: 'David Thomas, Andrew Hunt', year: 2019, content: 'Programming is a craft. A programmer is like a skilled carpenter, using tools and techniques to shape raw materials into useful objects. The pragmatic programmer takes responsibility for their work, communicates clearly, and continuously improves. Good enough software balances quality with delivery speed.', url: 'https://pragprog.com/titles/tpp20/', doi: '10.5555/3376219', language: 'en', type: 'book' },
  { id: 'prog-004', title: 'Clean Code: A Handbook of Agile Software Craftsmanship', author: 'Robert C. Martin', year: 2008, content: 'Even bad code can function. But if code is not clean, it can bring a development organization to its knees. Clean code is focused, each function does one thing well, and names reveal intention. Comments should explain why, not what. Functions should be small and do one thing.', url: 'https://www.oreilly.com/library/view/clean-code-a/9780136083238/', doi: '10.5555/1534519', language: 'en', type: 'book' },
  { id: 'prog-005', title: 'Design Patterns: Elements of Reusable Object-Oriented Software', author: 'Erich Gamma, Richard Helm, Ralph Johnson, John Vlissides', year: 1994, content: 'Design patterns are reusable solutions to commonly occurring problems in software design. They categorize object-oriented techniques into creational, structural, and behavioral patterns. The Observer, Strategy, Factory, and Singleton patterns are among the most widely used in modern software architecture.', url: 'https://books.google.com/books?id=6oHuKQe3TjQC', doi: '10.5555/186897', language: 'en', type: 'book' },
  { id: 'prog-006', title: 'Refactoring: Improving the Design of Existing Code', author: 'Martin Fowler', year: 2018, content: 'Refactoring is the process of changing a software system in such a way that it does not alter the external behavior of the code yet improves its internal structure. It is a disciplined way to clean up code that minimizes the chances of introducing bugs. Small behavior-preserving transformations are applied one after another.', url: 'https://martinfowler.com/books/refactoring.html', doi: '10.5555/3200593', language: 'en', type: 'book' },
  { id: 'prog-007', title: 'The Mythical Man-Month: Essays on Software Engineering', author: 'Frederick Brooks', year: 1975, content: 'Adding manpower to a late software project makes it later. This is Brooks Law. The fundamental problem is that software development is inherently complex, and no silver bullet will magically make it significantly easier. Conceptual integrity is the most important consideration in system design.', url: 'https://archive.org/details/mythicalmanmonth00fred', doi: '10.5555/207871', language: 'en', type: 'book' },
  { id: 'prog-008', title: 'JavaScript: The Good Parts', author: 'Douglas Crockford', year: 2008, content: 'JavaScript has a surprisingly large number of good ideas and bad ideas mixed together. The good ideas include functions, loose typing, dynamic objects, and an expressive object literal notation. The key is to learn to avoid the bad parts. Closures enable powerful functional programming patterns.', url: 'https://www.oreilly.com/library/view/javascript-the-good/9780596517748/', doi: '10.5555/1402357', language: 'en', type: 'book' },
  { id: 'prog-009', title: 'Effective Java', author: 'Joshua Bloch', year: 2018, content: 'Java is a powerful programming language and platform, but it has its traps and pitfalls. This book provides best practices for the Java programming language. Effective Java programming consists of knowing when to use each language feature and how to combine them effectively. Immutable objects are inherently thread-safe.', url: 'https://www.oreilly.com/library/view/effective-java/9780134686097/', doi: '10.5555/3325878', language: 'en', type: 'book' },
  { id: 'prog-010', title: 'Python Crash Course', author: 'Eric Matthes', year: 2019, content: 'Python is a great first programming language because of its clear and readable syntax. Python code reads almost like English, which makes it easier to learn and write. The language emphasizes code readability and allows expressing concepts in fewer lines of code. Python supports multiple programming paradigms.', url: 'https://nostarch.com/pythoncrashcourse2e', doi: '10.5555/3303698', language: 'en', type: 'book' },
  { id: 'prog-011', title: 'The C++ Programming Language', author: 'Bjarne Stroustrup', year: 2013, content: 'C++ is a general purpose programming language with a bias towards systems programming that supports data abstraction, object oriented programming, and generic programming. Classes enable user-defined types that behave as naturally as built-in types. Templates provide compile-time polymorphism.', url: 'https://www.stroustrup.com/4th.html', doi: '10.5555/2463984', language: 'en', type: 'book' },
  { id: 'prog-012', title: 'Eloquent JavaScript', author: 'Marijn Haverbeke', year: 2018, content: 'JavaScript lies at the heart of the web. It is a dynamic functional language with a prototype-based object system. First-class functions enable functional programming patterns. Asynchronous programming using callbacks, promises, and async/await is essential for web development.', url: 'https://eloquentjavascript.net/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'prog-013', title: 'You Don\'t Know JS', author: 'Kyle Simpson', year: 2015, content: 'JavaScript is one of the most popular programming languages. Understanding scope and closures is fundamental. The this keyword behaves differently from other languages. Prototypes provide a mechanism for inheritance. Asynchrony with promises and generators enables non-blocking code.', url: 'https://github.com/getify/You-Dont-Know-JS', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'prog-014', title: 'Functional Programming in Scala', author: 'Paul Chiusano, Runar Bjarnason', year: 2014, content: 'Functional programming is a paradigm that treats computation as the evaluation of mathematical functions and avoids changing state and mutable data. Pure functions have no side effects and always return the same output for the same input. Immutability eliminates entire classes of bugs related to shared mutable state.', url: 'https://www.manning.com/books/functional-programming-in-scala', doi: '10.5555/2769925', language: 'en', type: 'book' },
  { id: 'prog-015', title: 'The Go Programming Language', author: 'Alan Donovan, Brian Kernighan', year: 2015, content: 'Go is a general-purpose programming language. It has a clean syntax and efficient implementation. Goroutines enable lightweight concurrency with low overhead. Channels provide typed communication between goroutines. Interfaces enable duck typing without explicit declarations.', url: 'https://www.gopl.io/', doi: '10.5555/2886728', language: 'en', type: 'book' },

  // ==================== CIENCIA DE DATOS Y ANALYTICS ====================
  { id: 'data-001', title: 'The Elements of Statistical Learning', author: 'Trevor Hastie, Robert Tibshirani, Jerome Friedman', year: 2009, content: 'Data mining is the extraction of implicit, previously unknown, and potentially useful information from data. The goal is to develop algorithms that automatically build models from data for prediction and decision making. Statistical learning theory provides the mathematical foundation for understanding the bias-variance tradeoff.', url: 'https://hastie.su.domains/ElemStatLearn/', doi: '10.1007/978-0-387-84858-7', language: 'en', type: 'book' },
  { id: 'data-002', title: 'Python for Data Analysis', author: 'Wes McKinney', year: 2022, content: 'Data science is an interdisciplinary field that uses scientific methods, processes, algorithms and systems to extract knowledge and insights from structured and unstructured data. Pandas provides data structures and tools for working with tabular data. Data wrangling involves cleaning, transforming, and reshaping data.', url: 'https://wesmckinney.com/book/', doi: '10.5555/3376350', language: 'en', type: 'book' },
  { id: 'data-003', title: 'R for Data Science', author: 'Hadley Wickham, Garrett Grolemund', year: 2017, content: 'Data science is the discipline of making data useful. It involves importing, tidying, transforming, visualizing, and modeling data. Tidy data has variables in columns, observations in rows, and values in cells. The tidyverse is a collection of R packages designed for data science.', url: 'https://r4ds.had.co.nz/', doi: '10.5555/3161349', language: 'en', type: 'book' },
  { id: 'data-004', title: 'Data Science from Scratch', author: 'Joel Grus', year: 2019, content: 'To really learn data science, you should understand how libraries work by implementing them from scratch. This builds foundational knowledge of statistics, linear algebra, probability, and computer science. Machine learning is essentially teaching computers to make predictions based on patterns in data.', url: 'https://www.oreilly.com/library/view/data-science-from/9781492041142/', doi: '10.5555/3347054', language: 'en', type: 'book' },
  { id: 'data-005', title: 'Storytelling with Data', author: 'Cole Nussbaumer Knaflic', year: 2015, content: 'Effective data visualization is about communicating data clearly and efficiently. The goal is to make the data easy to understand and the insights actionable. Choosing the right chart type, using color strategically, and eliminating clutter are fundamental skills for data storytelling. Context matters for audience comprehension.', url: 'https://www.storytellingwithdata.com/', doi: '10.1002/9781119055251', language: 'en', type: 'book' },
  { id: 'data-006', title: 'Introduction to Information Retrieval', author: 'Christopher Manning, Prabhakar Raghavan, Hinrich Schutze', year: 2008, content: 'Information retrieval is the process of obtaining relevant documents in response to user queries. Inverted indices map terms to documents containing them. Term frequency-inverse document frequency assigns weights to terms based on importance. PageRank uses link structure to rank search results.', url: 'https://nlp.stanford.edu/IR-book/', doi: '10.1017/CBO9780511809071', language: 'en', type: 'book' },
  { id: 'data-007', title: 'Naked Statistics', author: 'Charles Wheelan', year: 2013, content: 'Statistics is the science of learning from data. Descriptive statistics summarize and describe features of a dataset. Inferential statistics use sample data to make generalizations about populations. Correlation measures the strength and direction of the relationship between two variables. Causation requires careful experimental design.', url: 'https://www.wwnorton.com/books/Naked-Statistics/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'data-008', title: 'Practical Statistics for Data Scientists', author: 'Peter Bruce, Andrew Bruce', year: 2020, content: 'Statistical methods are essential for data science. Exploratory data analysis uses visual and quantitative methods to understand data structure. Sampling and randomization are fundamental for drawing valid conclusions. Bootstrap methods estimate sampling distributions through resampling from data.', url: 'https://www.oreilly.com/library/view/practical-statistics-for/9781491952955/', doi: '10.5555/3404776', language: 'en', type: 'book' },
  { id: 'data-009', title: 'Think Stats', author: 'Allen Downey', year: 2014, content: 'Probability and statistics are mathematical foundations for data science. Probability mass functions describe the distribution of discrete random variables. Cumulative distribution functions give the probability that a variable is less than a given value. Hypothesis testing evaluates evidence for or against a hypothesis.', url: 'https://greenteapress.com/thinkstats/', doi: '10.5555/179163', language: 'en', type: 'book' },
  { id: 'data-010', title: 'Bayesian Methods for Hackers', author: 'Cameron Davidson-Pilon', year: 2015, content: 'Bayesian inference is a method of statistical inference in which Bayes theorem is used to update the probability for a hypothesis as more evidence becomes available. The prior distribution encodes initial beliefs. The posterior distribution combines prior beliefs with observed data. Markov chain Monte Carlo enables sampling from complex posterior distributions.', url: 'https://github.com/CamDavidsonPilon/Probabilistic-Programming-and-Bayesian-Methods-for-Hackers', doi: '10.5555/3345029', language: 'en', type: 'book' },

  // ==================== CIBERSEGURIDAD Y CRIPTOGRAFIA ====================
  { id: 'cyber-001', title: 'Computer Security: Principles and Practice', author: 'William Stallings, Lawrie Brown', year: 2022, content: 'Computer security is the protection of computer systems from theft, damage to hardware or software, and disruption of services. It involves confidentiality, integrity, and availability, known as the CIA triad. Security threats include malware, intruders, and denial of service attacks. Defense mechanisms include authentication, access control, and cryptography.', url: 'https://www.pearson.com/store/p/computer-security-principles-and-practice/', doi: '10.5555/3525943', language: 'en', type: 'book' },
  { id: 'cyber-002', title: 'Applied Cryptography', author: 'Bruce Schneier', year: 1996, content: 'Cryptography is the fundamental technology underlying most computer security. Symmetric encryption uses the same key for encryption and decryption. Asymmetric encryption uses a key pair: a public key for encryption and a private key for decryption. Hash functions produce fixed-size output from variable input and are essential for digital signatures.', url: 'https://www.schneier.com/books/applied_cryptography/', doi: '10.5555/236269', language: 'en', type: 'book' },
  { id: 'cyber-003', title: 'Security Engineering', author: 'Ross Anderson', year: 2020, content: 'Security engineering is about building systems that remain dependable in the face of malice, error, or mischance. It focuses on maintaining confidentiality, integrity, and availability despite hostile actions. Threat modeling identifies potential attack vectors. Security protocols must be designed to resist known attack models.', url: 'https://www.cl.cam.ac.uk/~rja14/book.html', doi: '10.5555/236269', language: 'en', type: 'book' },
  { id: 'cyber-004', title: 'The Web Application Hackers Handbook', author: 'Dafydd Stuttard, Marcus Pinto', year: 2011, content: 'Web application security involves identifying and exploiting vulnerabilities in web applications. Common vulnerabilities include SQL injection, cross-site scripting, and cross-site request forgery. Input validation and output encoding prevent injection attacks. Session management must protect against session hijacking and fixation.', url: 'https://www.wiley.com/en-us/The+Web+Application+Hacker%27s+Handbook%3A+Finding+and+Exploiting+Security+Flaws%2C+2nd+Edition-p-9781118026472', doi: '10.5555/207871', language: 'en', type: 'book' },
  { id: 'cyber-005', title: 'Metasploit: The Penetration Testers Guide', author: 'David Kennedy, Jim O Gorman, Devon Kearns', year: 2011, content: 'Penetration testing is the practice of testing a computer system, network, or web application to find vulnerabilities that an attacker could exploit. The Metasploit framework provides tools for developing and executing exploit code. Reconnaissance, scanning, exploitation, and post-exploitation are the phases of penetration testing.', url: 'https://nostarch.com/metasploit', doi: '10.5555/2023851', language: 'en', type: 'book' },
  { id: 'cyber-006', title: 'Hacking: The Art of Exploitation', author: 'Jon Erickson', year: 2008, content: 'Exploitation is the art of making software programs do unexpected things. Buffer overflow vulnerabilities occur when input exceeds the bounds of a buffer and overwrites adjacent memory. Shellcode is machine code designed to give an attacker a command shell. Understanding low-level programming is essential for both attackers and defenders.', url: 'https://nostarch.com/hacking2.htm', doi: '10.5555/1404395', language: 'en', type: 'book' },
  { id: 'cyber-007', title: 'OWASP Testing Guide', author: 'OWASP Foundation', year: 2024, content: 'Web application security testing is the process of analyzing web applications to identify security vulnerabilities. The guide covers information gathering, configuration management, authentication testing, authorization testing, and session management. OWASP Top 10 identifies the most critical web application security risks.', url: 'https://owasp.org/www-project-web-security-testing-guide/', doi: '10.13140/2.1.4685.5043', language: 'en', type: 'web' },
  { id: 'cyber-008', title: 'Cryptography Engineering', author: 'Niels Ferguson, Bruce Schneier, Tadayoshi Kohno', year: 2010, content: 'Designing cryptographic systems requires understanding not only cryptography but also systems engineering. Security is a chain only as strong as its weakest link. Key management is often the most difficult part of a cryptographic system. Side-channel attacks exploit information leakage from physical implementation.', url: 'https://www.wiley.com/en-us/Cryptography+Engineering%3A+Design+Principles+and+Practical+Applications-p-9780470474242', doi: '10.5555/179163', language: 'en', type: 'book' },
  { id: 'cyber-009', title: 'Serious Cryptography', author: 'Jean-Philippe Aumasson', year: 2017, content: 'Modern cryptography relies on mathematical hardness assumptions. Block ciphers encrypt fixed-size blocks using iterated round functions. Stream ciphers generate pseudorandom key streams. Authenticated encryption provides confidentiality and integrity. Cryptanalysis seeks weaknesses in cryptographic algorithms.', url: 'https://nostarch.com/seriouscrypto', doi: '10.5555/3203329', language: 'en', type: 'book' },
  { id: 'cyber-010', title: 'Blue Hat', author: 'Various Microsoft Conference Presentations', year: 2024, content: 'Security conferences bring together researchers and practitioners to share knowledge about vulnerabilities and defense techniques. Responsible disclosure involves reporting vulnerabilities to vendors before public release. Zero-day exploits target unknown vulnerabilities. Defense in depth uses multiple security controls to protect assets.', url: 'https://www.microsoft.com/en-us/security/blue-hat', doi: '10.13140/2.1.4685.5043', language: 'en', type: 'web' },

  // ==================== SISTEMAS Y REDES ====================
  { id: 'sys-001', title: 'Operating System Concepts', author: 'Abraham Silberschatz, Peter Galvin, Greg Gagne', year: 2018, content: 'An operating system is system software that manages computer hardware and software resources and provides common services for computer programs. Process scheduling algorithms determine which process runs at any given time. Memory management includes paging, segmentation, and virtual memory.', url: 'https://www.os-book.com/', doi: '10.5555/2636518', language: 'en', type: 'book' },
  { id: 'sys-002', title: 'Computer Networks', author: 'Andrew Tanenbaum, David Wetherall', year: 2011, content: 'A computer network is a set of computers connected together for sharing resources. The OSI reference model divides networking into seven layers. TCP/IP is the dominant protocol suite for the Internet. IP provides addressing and routing. TCP provides reliable, connection-oriented data delivery.', url: 'https://www.pearson.com/store/p/computer-networks/', doi: '10.5555/1974544', language: 'en', type: 'book' },
  { id: 'sys-003', title: 'Distributed Systems: Principles and Paradigms', author: 'Andrew Tanenbaum, Maarten Van Steen', year: 2017, content: 'A distributed system is a collection of independent computers that appears to its users as a single coherent system. Key challenges include transparency, scalability, reliability, and security. Consistency models define the behavior of replicated data. Fault tolerance enables systems to continue operating despite failures.', url: 'https://www.distributed-systems.net/', doi: '10.5555/1205990', language: 'en', type: 'book' },
  { id: 'sys-004', title: 'Computer Systems: A Programmers Perspective', author: 'Randal Bryant, David OHallaron', year: 2015, content: 'Understanding how computer systems execute programs enables programmers to write more efficient and reliable code. The processor executes machine-level instructions generated by compilers. Virtual memory gives each process the illusion of having exclusive use of main memory. Assembly language provides a human-readable representation of machine code.', url: 'https://csapp.cs.cmu.edu/', doi: '10.5555/2773144', language: 'en', type: 'book' },
  { id: 'sys-005', title: 'TCP/IP Illustrated', author: 'W. Richard Stevens', year: 1994, content: 'TCP/IP forms the foundation of Internet communications. IP provides unreliable, connectionless packet delivery. TCP adds reliable, connection-oriented data delivery with flow control and congestion control. UDP provides a simple, unreliable datagram service. Understanding these protocols is essential for network programming.', url: 'https://www.oreilly.com/library/view/tcpip-illustrated-volume/9780132808575/', doi: '10.5555/179163', language: 'en', type: 'book' },
  { id: 'sys-006', title: 'Site Reliability Engineering', author: 'Betsy Beyer, Chris Jones, Jennifer Petoff', year: 2016, content: 'Site reliability engineering applies software engineering principles to operations problems. SREs focus on automation, monitoring, incident response, and change management. Service level objectives define target reliability. Error budgets balance innovation with stability. Blameless postmortems enable continuous improvement.', url: 'https://sre.google/sre-book/', doi: '10.5555/3031449', language: 'en', type: 'book' },
  { id: 'sys-007', title: 'Modern Operating Systems', author: 'Andrew Tanenbaum', year: 2014, content: 'Modern operating systems must handle multiprogramming, virtual memory, file systems, and networking. Process concepts include creation, termination, states, and scheduling. File systems organize persistent storage. Device drivers provide standardized interfaces for hardware I/O. Multithreading enables concurrent execution.', url: 'https://www.pearson.com/store/p/modern-operating-systems/', doi: '10.5555/2505696', language: 'en', type: 'book' },
  { id: 'sys-008', title: 'Linux System Programming', author: 'Robert Love', year: 2013, content: 'System programming involves writing software that provides services to other software or directly interfaces with hardware. Linux system calls provide the interface between user programs and the kernel. File I/O operations use open, read, write, and close. Process management includes fork, exec, and wait for creating child processes.', url: 'https://www.oreilly.com/library/view/linux-system-programming/9781449341598/', doi: '10.5555/2505696', language: 'en', type: 'book' },
  { id: 'sys-009', title: 'Understanding the Linux Kernel', author: 'Daniel Bovet, Marco Cesati', year: 2005, content: 'The Linux kernel manages system resources and provides interfaces for user programs. Process scheduling uses the Completely Fair Scheduler. Memory management uses zones and the buddy system for allocation. The virtual file system provides a uniform interface to different file systems. Interrupt handlers respond to hardware events.', url: 'https://www.oreilly.com/library/view/understanding-the-linux/0596005652/', doi: '10.5555/1205990', language: 'en', type: 'book' },
  { id: 'sys-010', title: 'High Performance Browser Networking', author: 'Ilya Grigorik', year: 2013, content: 'Network performance depends on latency and bandwidth. TCP connection establishment and slow start affect performance. TLS handshake adds latency before data transfer. HTTP/2 enables multiplexing, header compression, and server push. WebSocket provides full-duplex communication over a single TCP connection.', url: 'https://hpbn.co/', doi: '10.5555/2636518', language: 'en', type: 'book' },

  // ==================== BASES DE DATOS ====================
  { id: 'db-001', title: 'Database System Concepts', author: 'Abraham Silberschatz, Henry Korth, S. Sudarshan', year: 2019, content: 'A database is a collection of interrelated data and programs to access that data. The database management system provides an environment that is convenient and efficient. SQL is the standard language for querying relational databases. Normalization eliminates redundancy through decomposition.', url: 'https://www.db-book.com/', doi: '10.5555/3337923', language: 'en', type: 'book' },
  { id: 'db-002', title: 'Database Management Systems', author: 'Raghu Ramakrishnan, Johannes Gehrke', year: 2003, content: 'The transaction concept ensures ACID properties: atomicity, consistency, isolation, and durability. Concurrency control protocols prevent interference between concurrent transactions. Recovery systems restore the database to a consistent state after failures. Query optimization selects efficient execution plans.', url: 'https://pages.cs.wisc.edu/~dbbook/', doi: '10.5555/1170794', language: 'en', type: 'book' },
  { id: 'db-003', title: 'Designing Data-Intensive Applications', author: 'Martin Kleppmann', year: 2017, content: 'Data-intensive applications need to store, process, and serve large volumes of data efficiently. Reliability means the system works correctly even when faults occur. Different data models optimize for different use cases. Replication provides redundancy and availability. Partitioning enables horizontal scaling.', url: 'https://www.oreilly.com/library/view/designing-data-intensive-applications/9781491903063/', doi: '10.5555/3060590', language: 'en', type: 'book' },
  { id: 'db-004', title: 'NoSQL Distilled', author: 'Pramod Sadalage, Martin Fowler', year: 2012, content: 'NoSQL databases emerged to address scalability and flexibility requirements. Key-value stores provide simple access patterns. Document databases store semi-structured data. Column-family stores organize data into column families. Graph databases excel at highly connected data. Polyglot persistence uses multiple technologies.', url: 'https://martinfowler.com/books/nosql.html', doi: '10.5555/236269', language: 'en', type: 'book' },
  { id: 'db-005', title: 'SQL Performance Explained', author: 'Markus Winand', year: 2012, content: 'Database performance depends on proper indexing and query formulation. B-tree indexes accelerate equality and range queries. The query optimizer uses statistics about data distribution to estimate costs. Full table scans can be efficient when accessing a large fraction of rows. Join algorithms include nested loops, hash joins, and merge joins.', url: 'https://use-the-index-luke.com/', doi: '10.13140/2.1.4685.5043', language: 'en', type: 'book' },
  { id: 'db-006', title: 'MongoDB: The Definitive Guide', author: 'Kristina Chodorow', year: 2013, content: 'MongoDB is a document-oriented database that stores data as BSON documents with dynamic schemas. Collections group related documents. Indexes support efficient query execution. Replication provides redundancy through replica sets. Sharding enables horizontal scaling by distributing data across machines.', url: 'https://www.oreilly.com/library/view/mongodb-the-definitive/9781449344803/', doi: '10.5555/2505696', language: 'en', type: 'book' },
  { id: 'db-007', title: 'PostgreSQL: Up and Running', author: 'Regina Obe, Leo Hsu', year: 2017, content: 'PostgreSQL is an advanced open-source relational database. It supports advanced data types including JSON, arrays, and geometric types. Extensions add functionality like PostGIS for geospatial data. MVCC enables high concurrency without read locks. Window functions enable advanced analytical queries.', url: 'https://www.oreilly.com/library/view/postgresql-up-and/9781491963402/', doi: '10.5555/3060590', language: 'en', type: 'book' },
  { id: 'db-008', title: 'Architecture of a Database System', author: 'Joseph Hellerstein, Michael Stonebraker', year: 2007, content: 'Database management systems have a layered architecture. The query processor parses, optimizes, and executes SQL queries. The storage manager handles files, buffers, and access methods. The transaction manager ensures ACID properties through concurrency control and recovery. Buffer management reduces disk I/O through caching.', url: 'https://dsf.berkeley.edu/papers/fntdb07-architecture.pdf', doi: '10.1561/1900000001', language: 'en', type: 'academic' },

  // ==================== ALGORITMOS Y ESTRUCTURAS DE DATOS ====================
  { id: 'algo-001', title: 'Introduction to Algorithms', author: 'Thomas Cormen, Charles Leiserson, Ronald Rivest, Clifford Stein', year: 2009, content: 'An algorithm is a finite sequence of well-defined instructions that solve a computational problem. Big-O notation characterizes asymptotic upper bounds on growth rates. Divide and conquer algorithms recursively break problems into smaller subproblems. Dynamic programming stores results to avoid recomputation.', url: 'https://mitpress.mit.edu/books/introduction-algorithms-third-edition', doi: '10.5555/1614191', language: 'en', type: 'book' },
  { id: 'algo-002', title: 'The Art of Computer Programming', author: 'Donald Knuth', year: 1997, content: 'The art of programming is the ability to organize a thousand lines of code at once, writing them correctly so they work together harmoniously. Information structures are fundamental ways to organize data: lists, trees, and graphs. Mathematical analysis reveals the principles that determine algorithm efficiency.', url: 'https://www-cs-faculty.stanford.edu/~knuth/taocp.html', doi: '10.5555/273356', language: 'en', type: 'book' },
  { id: 'algo-003', title: 'Algorithms', author: 'Robert Sedgewick, Kevin Wayne', year: 2011, content: 'Algorithms are step-by-step procedures for solving computational problems. Data structures organize data to enable efficient algorithms. Arrays provide constant-time random access. Linked lists enable efficient insertion and deletion. Hash tables provide near-constant-time lookup on average.', url: 'https://algs4.cs.princeton.edu/', doi: '10.5555/2020986', language: 'en', type: 'book' },
  { id: 'algo-004', title: 'The Algorithm Design Manual', author: 'Steven Skiena', year: 2008, content: 'The key to algorithm design is thinking about data the right way. Greedy algorithms build up solutions incrementally by making locally optimal choices. Backtracking explores search spaces systematically. Graph algorithms include traversal, shortest path, and minimum spanning tree problems.', url: 'http://www.algorist.com/', doi: '10.5555/1464150', language: 'en', type: 'book' },
  { id: 'algo-005', title: 'Grokking Algorithms', author: 'Aditya Bhargava', year: 2016, content: 'Binary search cuts the search space in half with each comparison, achieving O(log n) time complexity. Selection sort finds the smallest element repeatedly. Quicksort partitions around a pivot with average O(n log n) performance. Breadth-first search explores neighbors layer by layer to find shortest paths.', url: 'https://www.manning.com/books/grokking-algorithms', doi: '10.5555/3060590', language: 'en', type: 'book' },
  { id: 'algo-006', title: 'Cracking the Coding Interview', author: 'Gayle Laakmann McDowell', year: 2015, content: 'Technical interviews test candidates ability to solve algorithmic problems under time pressure. Key data structures include arrays, linked lists, stacks, queues, hash tables, trees, and graphs. Big-O analysis demonstrates understanding of time and space efficiency. Communication skills matter as much as coding ability.', url: 'https://www.crackingthecodinginterview.com/', doi: '10.5555/273356', language: 'en', type: 'book' },
  { id: 'algo-007', title: 'Data Structures and Algorithms in Java', author: 'Michael Goodrich, Roberto Tamassia', year: 2014, content: 'Data structures are systematic ways of organizing and accessing data. Stacks follow last-in-first-out discipline. Queues follow first-in-first-out discipline. Trees organize elements in hierarchical structures. Graphs model pairwise relationships among arbitrary objects.', url: 'https://www.wiley.com/en-us/Data+Structures+and+Algorithms+in+Java%2C+5th+Edition-p-9781118262166', doi: '10.5555/2544630', language: 'en', type: 'book' },
  { id: 'algo-008', title: 'Algorithmic Puzzles', author: 'Anany Levitin, Maria Levitin', year: 2011, content: 'Puzzles provide an engaging way to learn algorithmic thinking. The key is to recognize patterns and apply appropriate strategies. Brute force exhaustively searches all possibilities. Divide and conquer breaks problems into smaller parts. Dynamic programming applies when optimal solutions contain optimal solutions to subproblems.', url: 'https://global.oup.com/academic/product/algorithmic-puzzles-9780199740444', doi: '10.5555/2017115', language: 'en', type: 'book' },

  // ==================== INGENIERIA DE SOFTWARE ====================
  { id: 'se-001', title: 'Software Engineering: A Practitioners Approach', author: 'Roger Pressman, Bruce Maxim', year: 2014, content: 'Software engineering is the application of a systematic, disciplined, quantifiable approach to the development, operation, and maintenance of software. The software development life cycle includes requirements, design, coding, testing, and maintenance. Process models include waterfall, iterative, and agile approaches.', url: 'https://www.mheducation.com/highered/product/software-engineering-practitioner-s-approach-pressman-maxim/M0078022123.html', doi: '10.5555/2689705', language: 'en', type: 'book' },
  { id: 'se-002', title: 'Agile Software Development', author: 'Robert Martin', year: 2002, content: 'Agile development is an iterative and incremental approach emphasizing collaboration, working software, and responding to change. The SOLID principles guide object-oriented design: Single Responsibility, Open-Closed, Liskov Substitution, Interface Segregation, and Dependency Inversion. Test-driven development writes tests before code.', url: 'https://www.oreilly.com/library/view/agile-software-development/0135974445/', doi: '10.5555/572457', language: 'en', type: 'book' },
  { id: 'se-003', title: 'Code Complete', author: 'Steve McConnell', year: 2004, content: 'Code construction is the activity of creating working software by writing source code. High-quality code is readable, maintainable, and correct. Effective naming, commenting, and formatting make code easier to understand. Code reviews and testing verify correct behavior.', url: 'https://www.oreilly.com/library/view/code-complete-second/0735619670/', doi: '10.5555/109517', language: 'en', type: 'book' },
  { id: 'se-004', title: 'Domain-Driven Design', author: 'Eric Evans', year: 2003, content: 'Domain-driven design centers development on a rich domain model based on a deep understanding of the business domain. Ubiquitous language bridges the gap between technical and business teams. Bounded contexts define boundaries within which a model applies. Aggregates group related objects treated as a unit.', url: 'https://www.domainlanguage.com/ddd/', doi: '10.5555/862248', language: 'en', type: 'book' },
  { id: 'se-005', title: 'Software Architecture in Practice', author: 'Len Bass, Paul Clements, Rick Kazman', year: 2012, content: 'Software architecture defines the structures of a system, comprising software elements and their relationships. Architecture determines quality attributes like performance, security, and modifiability. Architectural patterns provide proven solutions to recurring design problems. Architecture documentation communicates design decisions.', url: 'https://www.oreilly.com/library/view/software-architecture-in/9780132943369/', doi: '10.5555/2505696', language: 'en', type: 'book' },
  { id: 'se-006', title: 'Continuous Delivery', author: 'Jez Humble, David Farley', year: 2010, content: 'Continuous delivery is a software development practice where code changes are automatically built, tested, and prepared for release to production. The deployment pipeline automates the path from commit to release. Infrastructure as code manages servers through version-controlled configuration. Blue-green deployments reduce deployment risk.', url: 'https://continuousdelivery.com/', doi: '10.5555/186897', language: 'en', type: 'book' },
  { id: 'se-007', title: 'The DevOps Handbook', author: 'Gene Kim, Patrick Debois, John Willis, Jez Humble', year: 2016, content: 'DevOps combines software development and IT operations to shorten the systems development life cycle. The Three Ways describe the principles: flow of work, feedback loops, and continuous learning. Continuous integration frequently merges code changes. Monitoring and metrics enable data-driven improvement.', url: 'https://itrevolution.com/the-devops-handbook/', doi: '10.5555/2963953', language: 'en', type: 'book' },
  { id: 'se-008', title: 'Test Driven Development', author: 'Kent Beck', year: 2002, content: 'Test-driven development is a software development process that relies on the repetition of a short cycle: write a failing test, write the minimum code to pass the test, and refactor. Red-green-refactor is the TDD mantra. Tests serve as documentation of expected behavior. TDD builds confidence to change code.', url: 'https://www.oreilly.com/library/view/test-driven-development/0321146530/', doi: '10.5555/572457', language: 'en', type: 'book' },

  // ==================== PROCESAMIENTO DE LENGUAJE NATURAL ====================
  { id: 'nlp-001', title: 'Speech and Language Processing', author: 'Dan Jurafsky, James Martin', year: 2024, content: 'Natural language processing enables computers to understand, interpret, and generate human language. Word embeddings represent words as dense vectors capturing semantic relationships. Word2Vec learns embeddings by predicting context words. Language models estimate the probability of word sequences.', url: 'https://web.stanford.edu/~jurafsky/slp3/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'nlp-002', title: 'Foundations of Statistical Natural Language Processing', author: 'Christopher Manning, Hinrich Schutze', year: 1999, content: 'Statistical methods have revolutionized natural language processing by enabling learning from large corpora. Part-of-speech tagging assigns grammatical categories using hidden Markov models. Named entity recognition identifies mentions of people, organizations, and locations. The noisy channel model provides a framework for spelling correction.', url: 'https://nlp.stanford.edu/fsnlp/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'nlp-003', title: 'Sequence to Sequence Learning with Neural Networks', author: 'Ilya Sutskever, Oriol Vinyals, Quoc Le', year: 2014, content: 'Sequence-to-sequence models map input sequences to output sequences of potentially different lengths. The encoder processes the input sequence into a context vector. The decoder generates the output sequence conditioned on this context. This architecture revolutionized machine translation and neural text generation.', url: 'https://arxiv.org/abs/1409.3215', doi: '10.48550/arXiv.1409.3215', language: 'en', type: 'academic' },
  { id: 'nlp-004', title: 'Neural Machine Translation by Jointly Learning to Align and Translate', author: 'Dzmitry Bahdanau, Kyunghyun Cho, Yoshua Bengio', year: 2015, content: 'Encoding a source sequence into a fixed-length vector creates a bottleneck for long sentences. Attention mechanisms allow the decoder to focus on different parts of the source sentence dynamically. The attention weight for each source position is computed by comparing decoder and encoder hidden states.', url: 'https://arxiv.org/abs/1409.0473', doi: '10.48550/arXiv.1409.0473', language: 'en', type: 'academic' },
  { id: 'nlp-005', title: 'Word2Vec: Efficient Estimation of Word Representations', author: 'Tomas Mikolov, Kai Chen, Greg Corrado, Jeffrey Dean', year: 2013, content: 'Distributed word representations capture semantic and syntactic information in continuous vector space. Skip-gram predicts context words given a target word. Continuous bag-of-words predicts the target word from context. Negative sampling simplifies training by sampling negative examples.', url: 'https://arxiv.org/abs/1301.3781', doi: '10.48550/arXiv.1301.3781', language: 'en', type: 'academic' },
  { id: 'nlp-006', title: 'GloVe: Global Vectors for Word Representation', author: 'Jeffrey Pennington, Richard Socher, Christopher Manning', year: 2014, content: 'GloVe combines the advantages of global matrix factorization and local context window methods. The model trains on word co-occurrence statistics from the entire corpus. Co-occurrence probabilities capture semantic relationships between words. The resulting embeddings capture analogies and similarity.', url: 'https://nlp.stanford.edu/projects/glove/', doi: '10.48550/arXiv.1409.0473', language: 'en', type: 'academic' },

  // ==================== VISION POR COMPUTADORA ====================
  { id: 'cv-001', title: 'Computer Vision: Algorithms and Applications', author: 'Richard Szeliski', year: 2022, content: 'Computer vision enables machines to derive meaningful information from images and video. Image processing operations include filtering, edge detection, and feature extraction. Feature matching identifies corresponding points between images. Segmentation partitions images into meaningful regions.', url: 'https://szeliski.org/Book/', doi: '10.1007/978-3-030-34215-1', language: 'en', type: 'book' },
  { id: 'cv-002', title: 'YOLO: Real-Time Object Detection', author: 'Joseph Redmon, Santosh Divvala, Ross Girshick, Ali Farhadi', year: 2016, content: 'You Only Look Once reframes object detection as a single regression problem. The image is divided into a grid, and each grid cell predicts bounding boxes and class probabilities directly. The model processes the entire image at once, enabling real-time performance. Non-maximum suppression removes duplicate predictions.', url: 'https://arxiv.org/abs/1506.02640', doi: '10.1109/CVPR.2016.91', language: 'en', type: 'academic' },
  { id: 'cv-003', title: 'Faster R-CNN: Towards Real-Time Object Detection', author: 'Shaoqing Ren, Kaiming He, Ross Girshick, Jian Sun', year: 2015, content: 'Faster R-CNN is an object detection network that uses a region proposal network to generate region proposals. The RPN shares convolutional features with the detection network. RoI pooling extracts fixed-length feature vectors from region proposals. End-to-end training improves detection accuracy.', url: 'https://arxiv.org/abs/1506.01497', doi: '10.1109/TPAMI.2016.2577031', language: 'en', type: 'academic' },
  { id: 'cv-004', title: 'FCN: Fully Convolutional Networks for Semantic Segmentation', author: 'Jonathan Long, Evan Shelhamer, Trevor Darrell', year: 2015, content: 'Fully convolutional networks replace fully connected layers with convolutional layers to output spatial maps instead of classification scores. Upsampling by learned deconvolution restores spatial resolution. Skip connections combine coarse semantic information with fine appearance details.', url: 'https://arxiv.org/abs/1411.4038', doi: '10.1109/CVPR.2015.7298645', language: 'en', type: 'academic' },
  { id: 'cv-005', title: 'Feature Extraction with SIFT', author: 'David Lowe', year: 2004, content: 'Scale-invariant feature transform detects distinctive keypoints that are invariant to scale, rotation, and illumination changes. SIFT constructs a scale-space pyramid by repeatedly smoothing and downsampling. Keypoints are identified as local extrema in scale-space. A 128-dimensional descriptor captures local gradient information.', url: 'https://www.cs.ubc.ca/~lowe/papers/ijcv04.pdf', doi: '10.1023/B:VISI.0000029664.99615.94', language: 'en', type: 'academic' },

  // ==================== REINFORCEMENT LEARNING ====================
  { id: 'rl-001', title: 'Reinforcement Learning: An Introduction', author: 'Richard Sutton, Andrew Barto', year: 2018, content: 'Reinforcement learning is learning what to do to maximize a numerical reward signal. An agent interacts with an environment, taking actions and receiving rewards. The goal is to learn a policy that maps states to actions maximizing cumulative reward. Value functions estimate expected cumulative reward from states or state-action pairs.', url: 'https://web.stanford.edu/class/psych209/Readings/SuttonBartoIPRLBook2ndEd.pdf', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'rl-002', title: 'Deep Q-Network', author: 'Volodymyr Mnih, Koray Kavukcuoglu, David Silver, Andrei Rusu', year: 2015, content: 'Deep Q-network combines reinforcement learning with deep neural networks to learn successful policies from high-dimensional sensory input. Experience replay stores transitions and samples mini-batches for training, breaking correlation. A separate target network provides stable targets. DQN achieved human-level performance on many Atari games.', url: 'https://www.nature.com/articles/nature14236', doi: '10.1038/nature14236', language: 'en', type: 'academic' },
  { id: 'rl-003', title: 'Proximal Policy Optimization Algorithms', author: 'John Schulman, Filip Wolski, Prafulla Dhariwal, Alec Radford', year: 2017, content: 'Proximal policy optimization constrains policy updates to avoid large destabilizing changes. A clipped surrogate objective limits how much the policy can change in each update. This strikes a balance between ease of implementation, sample efficiency, and ease of tuning. PPO has become a popular reinforcement learning algorithm.', url: 'https://arxiv.org/abs/1707.06347', doi: '10.48550/arXiv.1707.06347', language: 'en', type: 'academic' },
  { id: 'rl-004', title: 'Policy Gradient Methods for Reinforcement Learning', author: 'Richard Sutton, David McAllester, Satinder Singh, Yishay Mansour', year: 2000, content: 'Policy gradient methods optimize the policy directly by estimating the gradient of expected return with respect to policy parameters. REINFORCE uses sample returns to estimate the gradient. Actor-critic methods combine value function approximation with policy gradient for variance reduction.', url: 'https://proceedings.neurips.cc/paper/1999/file/464d828b85b0bed98e80ade0a5c43b0f-Paper.pdf', doi: '10.5555/3345029', language: 'en', type: 'academic' },

  // ==================== CLOUD Y DISTRIBUIDO ====================
  { id: 'cloud-001', title: 'Building Microservices', author: 'Sam Newman', year: 2021, content: 'Microservices architecture structures applications as a collection of loosely coupled, independently deployable services. Each service focuses on a single business capability. Services communicate through APIs, typically REST or message queues. Containers package services with their dependencies for consistent deployment.', url: 'https://www.oreilly.com/library/view/building-microservices-2nd/9781492033349/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'cloud-002', title: 'Kubernetes: Up and Running', author: 'Kelsey Hightower, Brendan Burns, Joe Beda', year: 2019, content: 'Kubernetes is an open-source container orchestration platform for automating deployment, scaling, and management of containerized applications. Pods are the smallest deployable units. Services provide stable network endpoints. Deployments manage replica sets and enable rollouts and rollbacks.', url: 'https://www.oreilly.com/library/view/kubernetes-up-and/9781492046523/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'cloud-003', title: 'MapReduce: Simplified Data Processing on Large Clusters', author: 'Jeffrey Dean, Sanjay Ghemawat', year: 2008, content: 'MapReduce is a programming model and implementation for processing large data sets in parallel across a cluster. Users specify a map function that processes key-value pairs and a reduce function that merges intermediate values. The runtime handles partitioning, scheduling, fault tolerance, and load balancing.', url: 'https://research.google/pubs/pub62/', doi: '10.1145/1327452.1327492', language: 'en', type: 'academic' },
  { id: 'cloud-004', title: 'The Google File System', author: 'Sanjay Ghemawat, Howard Gobioff, Shun-Tak Leung', year: 2003, content: 'The Google File System is a scalable distributed file system for large data-intensive applications. It provides fault tolerance by replicating files across multiple chunkservers. A single master maintains metadata and coordinates system operations. Files are divided into fixed-size chunks stored as regular files.', url: 'https://research.google/pubs/pub51/', doi: '10.1145/945445.945450', language: 'en', type: 'academic' },
  { id: 'cloud-005', title: 'Bigtable: A Distributed Storage System for Structured Data', author: 'Fay Chang, Jeffrey Dean, Sanjay Ghemawat', year: 2006, content: 'Bigtable is a distributed storage system for managing structured data that is designed to scale to a very large size. A Bigtable is a sparse, distributed, persistent multi-dimensional sorted map. The map is indexed by a row key, column key, and a timestamp. Each value in the map is an uninterpreted array of bytes.', url: 'https://research.google/pubs/pub27898/', doi: '10.1145/1290283.1290311', language: 'en', type: 'academic' },

  // ==================== ARQUITECTURA DE COMPUTADORES ====================
  { id: 'arch-001', title: 'Computer Architecture: A Quantitative Approach', author: 'John Hennessy, David Patterson', year: 2017, content: 'Computer architecture is the design and organization of computer systems. The instruction set architecture defines the interface between hardware and software. Pipelining overlaps instruction execution to improve throughput. Cache hierarchies reduce memory latency by exploiting locality.', url: 'https://www.elsevier.com/books/computer-architecture/hennessy/978-0-12-811905-1', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'arch-002', title: 'Computer Organization and Design', author: 'David Patterson, John Hennessy', year: 2020, content: 'The hardware-software interface defines how processors execute programs. The von Neumann architecture stores programs and data in the same memory. Assembly language provides a human-readable representation of machine instructions. Memory hierarchies balance cost and performance.', url: 'https://www.elsevier.com/books/computer-organization-and-design-patterson/978-0-12-811905-1', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'arch-003', title: 'Parallel Computer Architecture', author: 'David Culler, Jaswinder Singh, Anoop Gupta', year: 1998, content: 'Parallel computing uses multiple processors to solve problems faster. Shared memory multiprocessors provide a single address space. Distributed memory systems have private memory per processor and communicate through message passing. Cache coherence protocols maintain consistency across caches.', url: 'https://books.google.com/books?id=KSl6AAAAMAAJ', doi: '10.5555/3345029', language: 'en', type: 'book' },

  // ==================== COMPILADORES ====================
  { id: 'comp-001', title: 'Compilers: Principles, Techniques, and Tools', author: 'Alfred Aho, Monica Lam, Ravi Sethi, Jeffrey Ullman', year: 2006, content: 'A compiler translates source code from a high-level language to machine code. Lexical analysis groups characters into tokens. Syntax parsing constructs abstract syntax trees. Semantic analysis checks type consistency. Optimization transforms code to improve performance. Code generation produces target instructions.', url: 'https://suif.stanford.edu/dragonbook/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'comp-002', title: 'Engineering a Compiler', author: 'Keith Cooper, Linda Torczon', year: 2011, content: 'Modern compiler design balances compilation speed, code quality, and engineering complexity. Intermediate representations enable optimization across different phases. Data flow analysis computes liveness and available expressions. Register allocation maps virtual registers to hardware registers.', url: 'https://www.elsevier.com/books/engineering-a-compiler/cooper/978-0-12-088478-0', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'comp-003', title: 'Modern Compiler Implementation in ML', author: 'Andrew Appel', year: 1998, content: 'Functional programming languages provide elegant abstractions for compiler construction. Abstract syntax trees represent program structure. Pattern matching simplifies tree traversals. Continuation-passing style transforms control flow. Type systems for compiler intermediate languages catch bugs at compile time.', url: 'https://www.cs.princeton.edu/~appel/modern/ml/', doi: '10.5555/3345029', language: 'en', type: 'book' },

  // ==================== TEORIA DE LA COMPUTACION ====================
  { id: 'theory-001', title: 'Introduction to the Theory of Computation', author: 'Michael Sipser', year: 2012, content: 'The theory of computation studies what can and cannot be computed by machines. Finite automata model systems with finite memory, recognizing regular languages. Pushdown automata add a stack, recognizing context-free languages. Turing machines provide a mathematical model of computation.', url: 'https://www.cengage.com/c/introduction-to-the-theory-of-computation-3e-sipser/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'theory-002', title: 'Computational Complexity: A Modern Approach', author: 'Sanjeev Arora, Boaz Barak', year: 2009, content: 'Computational complexity studies the resources required to solve computational problems. P contains problems solvable in polynomial time. NP contains problems whose solutions can be verified in polynomial time. NP-completeness identifies the hardest problems in NP through reductions.', url: 'https://theory.cs.princeton.edu/complexity/', doi: '10.1017/CBO9780511804090', language: 'en', type: 'book' },
  { id: 'theory-003', title: 'Introduction to Automata Theory, Languages, and Computation', author: 'John Hopcroft, Rajeev Motwani, Jeffrey Ullman', year: 2006, content: 'Formal languages are sets of strings defined by grammars or automata. Regular expressions describe patterns using concatenation, union, and closure. Deterministic and nondeterministic finite automata recognize exactly the regular languages. Context-free grammars describe programming language syntax.', url: 'https://www.pearson.com/store/p/introduction-to-automata-theory-languages-and-computation/', doi: '10.5555/3345029', language: 'en', type: 'book' },

  // ==================== GRAFICAS COMPUTACIONALES ====================
  { id: 'graphics-001', title: 'Computer Graphics: Principles and Practice', author: 'John Hughes, Andries van Dam, Morgan McGuire, David Sklar', year: 2013, content: 'Computer graphics generates images from geometric models and scene descriptions. Rendering computes light transport from light sources through surfaces to the camera. Rasterization converts geometric primitives into pixel colors. Ray tracing computes light paths by casting rays through pixels.', url: 'https://cgpp.net/about.xml', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'graphics-002', title: 'Real-Time Rendering', author: 'Tomas Akenine-Moller, Eric Haines, Naty Hoffman', year: 2018, content: 'Real-time rendering generates images fast enough for interactive applications. The graphics pipeline transforms vertices, rasterizes primitives, and processes fragments. Shaders are programs running on the GPU. Shadow mapping renders shadows by projecting depths from the light view.', url: 'https://www.realtimerendering.com/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'graphics-003', title: 'Physically Based Rendering: From Theory to Implementation', author: 'Matt Pharr, Wenzel Jakob, Greg Humphreys', year: 2016, content: 'Physically based rendering simulates light transport to create realistic images. The rendering equation describes energy equilibrium between surfaces. Monte Carlo integration estimates global illumination through sampling. Path tracing traces random light paths accumulating radiance.', url: 'https://pbr-book.org/', doi: '10.5555/3345029', language: 'en', type: 'book' },

  // ==================== COMPUTO CUANTICO ====================
  { id: 'quantum-001', title: 'Quantum Computation and Quantum Information', author: 'Michael Nielsen, Isaac Chuang', year: 2010, content: 'Quantum computing harnesses quantum mechanical phenomena for computation. Qubits are quantum bits that exist in superposition of zero and one. Quantum entanglement creates correlations between qubits. Quantum algorithms like Shors algorithm factor integers exponentially faster than classical algorithms.', url: 'https://michaelnielsen.org/qcqi/', doi: '10.1017/CBO9780511976667', language: 'en', type: 'book' },
  { id: 'quantum-002', title: 'Programming Quantum Computers', author: 'Eric Johnson, Nic Harrigan, Mercedes Gimeno-Segovia', year: 2019, content: 'Quantum programming languages express quantum circuits and algorithms. Quantum circuits apply gates in sequence to qubits. The Hadamard gate creates superposition states. CNOT gates create entanglement between qubits. Quantum simulators run quantum algorithms on classical computers.', url: 'https://www.oreilly.com/library/view/programming-quantum-computers/9781492039456/', doi: '10.5555/3345029', language: 'en', type: 'book' },

  // ==================== ETICA Y SOCIEDAD ====================
  { id: 'ethics-001', title: 'Weapons of Math Destruction', author: 'Cathy ONeil', year: 2016, content: 'Algorithms increasingly influence important decisions about credit, employment, and criminal justice. Weapons of math destruction are algorithms that are opaque, harmful, and difficult to contest. Feedback loops reinforce existing biases. Algorithmic auditing reveals disparate impact across demographic groups.', url: 'https://www.penguinrandomhouse.com/books/242361/weapons-of-math-destruction-by-cathy-oneil/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'ethics-002', title: 'Human Compatible: AI and the Problem of Control', author: 'Stuart Russell', year: 2019, content: 'AI systems need to be designed to be beneficial to humans. The alignment problem concerns ensuring AI systems pursue goals aligned with human values. Inverse reinforcement learning infers human preferences from observed behavior. Provably beneficial AI requires formalizing human preferences.', url: 'https://www.penguinrandomhouse.com/books/598863/human-compatible-by-stuart-russell/', doi: '10.5555/3345029', language: 'en', type: 'book' },
  { id: 'ethics-003', title: 'Fairness and Machine Learning', author: 'Solon Barocas, Moritz Hardt, Arvind Narayanan', year: 2019, content: 'Fairness in machine learning concerns preventing discriminatory outcomes. Statistical parity requires equal positive prediction rates across groups. Equalized odds requires equal true positive and false positive rates. Fairness constraints can conflict with accuracy. Counterfactual fairness considers whether outcomes would differ if an individual belonged to a different group.', url: 'https://fairmlbook.org/', doi: '10.5555/3345029', language: 'en', type: 'book' },

  ...additionalSourceDocuments1,
  ...additionalSourceDocuments2,
  ...additionalSourceDocuments3,
  ...additionalSourceDocuments4,
  ...additionalSourceDocuments5,
  ...additionalSourceDocuments6,
];

